WITH cleaned AS (SELECT id, product_name, category, price, cost, stock_qty, launch_date, tags, supplier_id, CONCAT(product_name, ', ', brand) product_name_brand FROM products WHERE launch_date >= DATE '2023-04-18' AND supplier_id IS NOT NULL) SELECT * FROM (SELECT supplier_id, category, stock_qty FROM cleaned) src PIVOT (MAX(stock_qty) AS amount, COUNT(1) AS item_count FOR category IN ('Grocery', 'Books', 'Home'));
